const items = $input.all();
const results = [];
for (const item of items) {
  const list = (item.json && Array.isArray(item.json.data)) ? item.json.data : [];
  for (const wf of list) {
    if (wf.isArchived === true) continue;
    const safeName = String(wf.name || wf.id)
      .replace(/[\\/:*?"<>|]+/g, "_")
      .replace(/\s+/g, "_")
      .replace(/_+/g, "_")
      .replace(/^_+|_+$/g, "")
      .slice(0, 100);
    results.push({
      json: {
        id: wf.id,
        name: wf.name,
        active: wf.active === true,
        isArchived: wf.isArchived === true,
        filename: "workflows/" + safeName + "__" + wf.id + ".json"
      }
    });
  }
}
return results;

// Runs once, after the commits (or straight away when nothing changed).
const prepItems = $('Prepare Commit').all().map(i => i.json);
const stats = (prepItems[0] && prepItems[0].stats) || { listed: 0, unchanged: 0, toCommit: 0, fetchFailed: [] };
const toCommit = prepItems.filter(j => j.noop !== true);
let commits = [];
if (toCommit.length > 0) {
  try { commits = $('Commit to GitHub').all().map(i => i.json); } catch (e) { commits = []; }
}
let committed = 0;
let added = 0;
const failures = (stats.fetchFailed || []).slice();
for (let i = 0; i < toCommit.length; i++) {
  const c = commits[i] || {};
  if (c.commit && typeof c.commit.sha === 'string') {
    committed += 1;
    if (toCommit[i].isNew) added += 1;
    continue;
  }
  let msg = 'Unknown error';
  if (c.error) { msg = c.error.message || JSON.stringify(c.error); }
  else if (c.message) { msg = c.message; }
  failures.push({ file: toCommit[i].filename, error: String(msg).slice(0, 200) });
}
const ok = stats.unchanged + committed;
const failed = failures.length;
const status = failed === 0 ? 'success' : (ok === 0 ? 'failure' : 'partial');
const icon = status === 'success' ? ':white_check_mark:' : (status === 'partial' ? ':warning:' : ':x:');
const dateStr = new Date().toISOString().slice(0, 10);
let message = icon + ' *n8n Backup ' + dateStr + '* - ' + ok + '/' + stats.listed + ' workflows backed up to `antonioefm/n8nbackup` (' + committed + ' changed' + (added > 0 ? ', of which ' + added + ' new' : '') + ', ' + stats.unchanged + ' unchanged)';
if (failed > 0) {
  message += '\n\n*Issues (' + failed + '):*\n';
  for (const f of failures.slice(0, 10)) { message += '- `' + f.file + '`: ' + f.error + '\n'; }
  if (failed > 10) { message += '_...and ' + (failed - 10) + ' more_'; }
}
return [{ json: { status: status, listed: stats.listed, committed: committed, added: added, unchanged: stats.unchanged, failed: failed, message: message } }];

// Compares each workflow with the copy already in the repo and keeps only new or changed files.
// Git stores a file's blob SHA as sha1('blob <bytes>\0<content>'), so an identical file has an identical SHA.
const crypto = require('crypto');
const blobSha = (s) => {
  const b = Buffer.from(s, 'utf8');
  return crypto.createHash('sha1').update(Buffer.concat([Buffer.from('blob ' + b.length + '\0', 'utf8'), b])).digest('hex');
};
const tree = $('Get repo tree').first().json;
if (!Array.isArray(tree.tree) || tree.truncated === true) {
  throw new Error('Could not read the full file list of the backup repo (tree missing or truncated). Nothing was committed.');
}
const repo = {};
for (const e of tree.tree) { if (e.type === 'blob') repo[e.path] = e.sha; }

const metas = $('Filter and Prep Workflows').all();
const fetched = $input.all();
const dateStr = new Date().toISOString().slice(0, 10);
const out = [];
let unchanged = 0;
const fetchFailed = [];
for (let i = 0; i < fetched.length; i++) {
  const p = fetched[i].pairedItem;
  const idx = (p && typeof p.item === 'number') ? p.item : i;
  const meta = (metas[idx] || {}).json || {};
  const wf = fetched[i].json || {};
  if (typeof wf.id !== 'string' || !Array.isArray(wf.nodes)) {
    fetchFailed.push({ file: meta.filename || 'unknown', error: 'Workflow fetch failed' });
    continue;
  }
  const text = JSON.stringify(wf, null, 2);
  const existing = repo[meta.filename] || null;
  if (existing && existing === blobSha(text)) { unchanged += 1; continue; }
  const body = { message: 'Daily backup ' + dateStr + ' - ' + meta.name, content: Buffer.from(text, 'utf8').toString('base64'), branch: 'main' };
  if (existing) body.sha = existing;
  out.push({ json: { filename: meta.filename, workflowName: meta.name, workflowId: meta.id, isNew: !existing, bodyJson: JSON.stringify(body) } });
}
const stats = { listed: metas.length, unchanged: unchanged, toCommit: out.length, fetchFailed: fetchFailed };
if (out.length === 0) { return [{ json: { noop: true, stats: stats } }]; }
for (const o of out) { o.json.stats = stats; }
return out;

